import{_ as o,l as i,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"失业保险与道德风险","description":"","frontmatter":{"title":"失业保险与道德风险","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ui-moral-hazard.md","filePath":"econ/ui-moral-hazard.md","lastUpdated":1789023840000}'),E={name:"econ/ui-moral-hazard.md"};function c(m,a,B,A,u,_){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="失业保险与道德风险" tabindex="-1">失业保险与道德风险 <a class="header-anchor" href="#失业保险与道德风险" aria-label="Permalink to &quot;失业保险与道德风险&quot;">​</a></h1><div class="epigraph"><p>失业是可观测的大冲击，保险价值高；但替代率把搜寻的影子价格压低，最优 UI 是保险与激励的权衡。</p><footer>—— Baily, Some Aspects of Optimal Unemployment Insurance, JPubE 1978；Chetty, A General Formula for the Optimal Level of Unemployment Insurance, JPubE 2006</footer></div><p><a href="/econ/income-risk-insurance">上一课</a>的部分保险把失业混在一般 \\(z\\) 里。本课缺口是把<strong>失业</strong>单独钉成合约对象：Baily–Chetty 公式。不重估全部传递系数，不把搜寻理论从零推导。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失业冲击大、可验证（相对健康的努力），政府 UI 补市场缺失。道德风险：更长的受益期、更高的替代率延长失业持续时间（Meyer 等经验）。Baily：最优替代率使保险的消费平滑收益等于持续时间弹性带来的财政与效率成本。Chetty 把公式写成可用消费掉落与持续弹性校准的充分统计。缺口是给自动稳定器一个微观福利语言，而不是再讲一次 HANK 转移。</p><p><span class="marginnote">Baily, <em>JPubE</em> 1978。Chetty, <em>JPubE</em> 2006。Shavell and Weiss 的递减给付。Landais, Michaillat and Saez 把宏观劳动力市场松紧接进最优 UI。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>充分统计：失业时消费掉落 \\(\\Delta c/c\\)、相对风险厌恶、失业持续时间对 UI 的弹性。宏观：衰退中空岗少，弹性的效率成本下降，最优 UI 可更慷慨——与 HANK 稳定器同向，机制是匹配而不是 MPC。搜寻模型（McCall、DMP）提供弹性的结构来源；本课用弹性，不重写匹配函数。</p>',8)),(e(),s(p,null,{default:r(()=>[h(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E5%A4%B1%E4%B8%9A%E6%97%B6%20u'(c)%20%E8%B7%B3%E9%AB%98%22%5D%20--%3E%20GAIN%5B%22%E4%BF%9D%E9%99%A9%E6%94%B6%E7%9B%8A%22%5D%0A%20%20MH%5B%22%E6%8C%81%E7%BB%AD%E6%97%B6%E9%97%B4%E5%BC%B9%E6%80%A7%22%5D%20--%3E%20COST%5B%22%E8%B4%A2%E6%94%BF%E4%B8%8E%E4%BA%A7%E5%87%BA%E6%88%90%E6%9C%AC%22%5D%0A%20%20GAIN%20--%3E%20OPT%5B%22Baily-Chetty%20%E6%9B%BF%E4%BB%A3%E7%8E%87%22%5D%0A%20%20COST%20--%3E%20OPT%0A%20%20SLACK%5B%22%E5%8A%B3%E5%8A%A8%E5%8A%9B%E5%B8%82%E5%9C%BA%E6%9D%BE%22%5D%20--%3E%20COST%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>HANK 里 UI 还改变高 MPC 群体的收入，乘数是副产品；本课主产品是福利权衡。两者可同时报，不要只报乘数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是隐藏的搜寻努力（或保留工资）对给付敏感。完全监测则无道德风险，只需保险。现实监测有限。资产：有缓冲的人持续时间弹性可能不同（Chetty 的流动性与道德风险分解）：一部分「更长失业」其实是流动性放松后的最优等待，不一定是社会浪费。这把缓冲存量课接到 UI，而不是新偏好。</p><p><span class="marginnote">经验：Card, Chetty and Weber；Schmieder and von Wachter 综述。本课不引用虚构编号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定具体国家的法定周数。不把残障保险、提前退休写完。企业经验费率、经历评级是同一权衡的企业侧。主权财政能否发 UI 取决于后课债务，这里假设政府能发债或征税。</p><p>后课默认：UI 用 Baily–Chetty 权衡；宏观松紧可改弹性成本。下一课：家庭不只被收入砸，还被杠杆砸——债务与周期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优 UI：消费平滑收益 vs 持续时间弹性成本。</li><li>充分统计可校准；松市场可提高最优慷慨度。</li><li>流动性效应与纯道德风险要分开。</li><li>出处：Baily, <em>JPubE</em> 1978；Chetty, <em>JPubE</em> 2006。</li></ul>',9))])}const P=o(E,[["render",c]]);export{f as __pageData,P as default};
